function agenda(){const minutes=({'60':[5,10,15,0,20,10],'120':[10,20,30,10,30,20],'180':[15,30,50,10,50,25],'300':[20,50,80,20,90,40]})[state.profile.duration]||[10,20,30,10,30,20];const transfer=(from,to,n)=>{const amount=Math.max(0,Math.min(n,minutes[from]-5));minutes[from]-=amount;minutes[to]+=amount};if(state.profile.experience==='new')transfer(2,1,5);if(state.profile.experience==='experienced')transfer(1,2,5);if(state.profile.stage==='active')transfer(0,2,5);if(state.profile.stage==='proposal')transfer(2,4,5);if(state.profile.team==='distributed')transfer(2,4,5);return t.phase.map(([title,text],i)=>({i,title,minutes:state.agenda[i]?.minutes??minutes[i],text:state.agenda[i]?.text??(text+(i===0?' '+t.stage_text[state.profile.stage]:i===1?' '+t.experience_text[state.profile.experience]:i===2?' '+t.focus.filter(([id])=>has(id)).map(x=>x[1]).join('; '):''))})).filter(r=>r.i!==3||r.minutes>0)}
